//! The IANA time zone database (`tzdata.txt`, generated by scripts/gen-tzdata.py from an
//! IANA tzdata release) for Temporal's named time zones and Date's local time.
//!
//! A zone is its UT offsets, the instants where the offset changes, and a POSIX TZ rule
//! (RFC 9636 §3.3) for instants after the last listed one. Times here are seconds since the
//! epoch; offsets are seconds east of UT.

use super::fx::HashMap;
use std::sync::OnceLock;

const DATA: &str = include_str!("tzdata.txt");

pub struct Zone {
    pub name: &'static str,
    offsets: Vec<i32>,
    /// (instant, offset index) in increasing instant order; each changes the offset.
    trans: Vec<(i64, u8)>,
    rule: Option<Rule>,
}

struct Db {
    zones: Vec<Zone>,
    /// Lowercased identifier → (zone, the identifier as the database spells it).
    names: HashMap<String, (usize, &'static str)>,
    /// The tzdata release, e.g. "2026e".
    version: &'static str,
}

fn parse36(s: &str) -> i64 {
    let (neg, digits) = match s.strip_prefix('-') {
        Some(d) => (true, d),
        None => (false, s),
    };
    let v = i64::from_str_radix(digits, 36).unwrap_or(0);
    if neg {
        -v
    } else {
        v
    }
}

fn db() -> &'static Db {
    static DB: OnceLock<Db> = OnceLock::new();
    DB.get_or_init(|| {
        let mut zones = Vec::new();
        let mut names = HashMap::default();
        let mut links = Vec::new();
        let mut version = "";
        for line in DATA.lines() {
            if let Some(v) = line.strip_prefix("# IANA tzdata ") {
                version = v;
            } else if let Some(z) = line.strip_prefix("Z ") {
                let mut parts = z.splitn(4, '|');
                let name = parts.next().unwrap_or("");
                let rule = parts.next().unwrap_or("");
                let offsets = parts.next().unwrap_or("").split(',').filter_map(|o| o.parse().ok()).collect();
                let mut t = 0i64;
                let trans = parts
                    .next()
                    .unwrap_or("")
                    .split(' ')
                    .filter(|p| !p.is_empty())
                    .filter_map(|p| {
                        let (d, i) = p.split_once(':')?;
                        t += parse36(d);
                        Some((t, i.parse().ok()?))
                    })
                    .collect();
                names.insert(name.to_ascii_lowercase(), (zones.len(), name));
                zones.push(Zone { name, offsets, trans, rule: Rule::parse(rule) });
            } else if let Some(l) = line.strip_prefix("L ") {
                if let Some((link, target)) = l.split_once(' ') {
                    links.push((link, target));
                }
            }
        }
        for (link, target) in links {
            if let Some(&(z, _)) = names.get(&target.to_ascii_lowercase()) {
                names.insert(link.to_ascii_lowercase(), (z, link));
            }
        }
        Db { zones, names, version }
    })
}

/// The tzdata release the table was made from.
pub fn version() -> &'static str {
    db().version
}

/// GetAvailableNamedTimeZoneIdentifier: (identifier as the database spells it, primary
/// identifier) for a case-insensitive name. "UTC" is the primary of the UTC zones.
pub fn lookup(name: &str) -> Option<(&'static str, &'static str)> {
    let d = db();
    let &(z, spelled) = d.names.get(&name.to_ascii_lowercase())?;
    let primary = match d.zones[z].name {
        "Etc/UTC" | "Etc/GMT" => "UTC",
        p => p,
    };
    // "UTC" itself is a link to Etc/UTC in the database.
    let spelled = if spelled.eq_ignore_ascii_case("utc") { "UTC" } else { spelled };
    Some((spelled, primary))
}

pub fn zone(name: &str) -> Option<&'static Zone> {
    let d = db();
    let lower = name.to_ascii_lowercase();
    let key = if lower == "utc" { "etc/utc".to_string() } else { lower };
    d.names.get(&key).map(|&(z, _)| &d.zones[z])
}

impl Zone {
    /// The UT offset at instant `t`.
    pub fn offset_at(&self, t: i64) -> i32 {
        let last = self.trans.last().map(|x| x.0);
        if let (Some(r), Some(l)) = (&self.rule, last) {
            if t >= l {
                return r.offset_at(t);
            }
        }
        if let (Some(r), None) = (&self.rule, last) {
            return r.offset_at(t);
        }
        match self.trans.partition_point(|x| x.0 <= t) {
            0 => self.offsets.first().copied().unwrap_or(0),
            k => self.offsets[self.trans[k - 1].1 as usize],
        }
    }

    /// The instants whose local time is `local` (seconds of a local date-time read as
    /// UT): none in a gap, two in an overlap (GetNamedTimeZoneEpochNanoseconds).
    pub fn possible(&self, local: i64) -> Vec<i64> {
        let mut out: Vec<i64> = Vec::new();
        for o in [self.offset_at(local - 86400), self.offset_at(local + 86400)] {
            let t = local - o as i64;
            if self.offset_at(t) == o && !out.contains(&t) {
                out.push(t);
            }
        }
        out.sort_unstable();
        out
    }

    /// The first offset change strictly after `t`.
    pub fn next_transition(&self, t: i64) -> Option<i64> {
        let k = self.trans.partition_point(|x| x.0 <= t);
        if k < self.trans.len() {
            return Some(self.trans[k].0);
        }
        let r = self.rule.as_ref()?;
        let after = t.max(self.trans.last().map_or(i64::MIN, |x| x.0));
        r.next_after(after)
    }

    /// The last offset change strictly before `t`.
    pub fn previous_transition(&self, t: i64) -> Option<i64> {
        let last = self.trans.last().map(|x| x.0);
        if let Some(r) = &self.rule {
            if let Some(p) = r.previous_before(t) {
                if last.is_none_or(|l| p > l) {
                    return Some(p);
                }
            }
        }
        match self.trans.partition_point(|x| x.0 < t) {
            0 => None,
            k => Some(self.trans[k - 1].0),
        }
    }
}

/// A POSIX TZ rule: a standard offset, and maybe a DST offset with the dates it starts and
/// ends each year.
struct Rule {
    std: i32,
    dst: Option<(i32, When, When)>,
}

/// A rule date (Jn, n or Mm.w.d) and local time of day in seconds (may be < 0 or > 24h).
#[derive(Clone, Copy)]
struct When {
    date: RuleDate,
    time: i64,
}

#[derive(Clone, Copy)]
enum RuleDate {
    /// Day 1–365, February 29 never counted.
    Julian(u32),
    /// Day 0–365, counting February 29.
    Zero(u32),
    /// Month 1–12, week 1–5 (5: the last), weekday 0–6 (Sunday first).
    Month(u32, u32, u32),
}

struct P<'a> {
    s: &'a [u8],
    i: usize,
}

impl P<'_> {
    fn peek(&self) -> Option<u8> {
        self.s.get(self.i).copied()
    }
    fn name(&mut self) -> Option<()> {
        if self.peek() == Some(b'<') {
            while self.peek()? != b'>' {
                self.i += 1;
            }
            self.i += 1;
            return Some(());
        }
        let st = self.i;
        while self.peek().is_some_and(|c| c.is_ascii_alphabetic()) {
            self.i += 1;
        }
        (self.i > st).then_some(())
    }
    fn num(&mut self) -> Option<i64> {
        let st = self.i;
        while self.peek().is_some_and(|c| c.is_ascii_digit()) {
            self.i += 1;
        }
        std::str::from_utf8(&self.s[st..self.i]).ok()?.parse().ok()
    }
    /// [+-]hh[:mm[:ss]] in seconds.
    fn hms(&mut self) -> Option<i64> {
        let sign = match self.peek() {
            Some(b'-') => {
                self.i += 1;
                -1
            }
            Some(b'+') => {
                self.i += 1;
                1
            }
            _ => 1,
        };
        let mut v = self.num()? * 3600;
        for unit in [60, 1] {
            if self.peek() == Some(b':') {
                self.i += 1;
                v += self.num()? * unit;
            } else {
                break;
            }
        }
        Some(sign * v)
    }
    fn when(&mut self) -> Option<When> {
        let date = match self.peek()? {
            b'J' => {
                self.i += 1;
                RuleDate::Julian(self.num()? as u32)
            }
            b'M' => {
                self.i += 1;
                let m = self.num()? as u32;
                self.i += 1;
                let w = self.num()? as u32;
                self.i += 1;
                RuleDate::Month(m, w, self.num()? as u32)
            }
            _ => RuleDate::Zero(self.num()? as u32),
        };
        let time = if self.peek() == Some(b'/') {
            self.i += 1;
            self.hms()?
        } else {
            7200
        };
        Some(When { date, time })
    }
}

impl Rule {
    fn parse(s: &str) -> Option<Rule> {
        if s.is_empty() {
            return None;
        }
        let mut p = P { s: s.as_bytes(), i: 0 };
        p.name()?;
        // POSIX offsets are west of UT.
        let std = -p.hms()? as i32;
        if p.peek().is_none() {
            return Some(Rule { std, dst: None });
        }
        p.name()?;
        let dst = if p.peek().is_some_and(|c| c != b',') { -p.hms()? as i32 } else { std + 3600 };
        if p.peek() != Some(b',') {
            return Some(Rule { std, dst: None });
        }
        p.i += 1;
        let start = p.when()?;
        p.i += 1;
        let end = p.when()?;
        Some(Rule { std, dst: Some((dst, start, end)) })
    }

    /// The year's DST start and end instants.
    fn bounds(&self, year: i64) -> Option<(i64, i64)> {
        let (dst, start, end) = self.dst?;
        let s = day_of(year, start.date) * 86400 + start.time - self.std as i64;
        let e = day_of(year, end.date) * 86400 + end.time - dst as i64;
        Some((s, e))
    }

    fn offset_at(&self, t: i64) -> i32 {
        let Some((dst, ..)) = self.dst else { return self.std };
        let Some((s, e)) = self.bounds(year_of(t + self.std as i64)) else { return self.std };
        // Northern rules have DST between start and end; southern ones outside them.
        let in_dst = if s < e { t >= s && t < e } else { t >= s || t < e };
        if in_dst {
            dst
        } else {
            self.std
        }
    }

    fn transitions(&self, year: i64) -> Vec<i64> {
        match self.bounds(year) {
            Some((s, e)) if self.dst.is_some_and(|d| d.0 != self.std) => {
                let mut v = vec![s, e];
                v.sort_unstable();
                v
            }
            _ => Vec::new(),
        }
    }

    fn next_after(&self, t: i64) -> Option<i64> {
        let y = year_of(t);
        (y - 1..=y + 2).flat_map(|yy| self.transitions(yy)).filter(|&x| x > t).min()
    }

    fn previous_before(&self, t: i64) -> Option<i64> {
        let y = year_of(t);
        (y - 2..=y + 1).flat_map(|yy| self.transitions(yy)).filter(|&x| x < t).max()
    }
}

fn is_leap(y: i64) -> bool {
    y % 4 == 0 && (y % 100 != 0 || y % 400 == 0)
}

/// Days from the epoch to year-month-day (proleptic Gregorian).
fn days_from_civil(y: i64, m: i64, d: i64) -> i64 {
    let y = if m <= 2 { y - 1 } else { y };
    let era = y.div_euclid(400);
    let yoe = y - era * 400;
    let mp = (m + 9) % 12;
    let doy = (153 * mp + 2) / 5 + d - 1;
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    era * 146097 + doe - 719468
}

fn year_of(t: i64) -> i64 {
    let days = t.div_euclid(86400);
    let z = days + 719468;
    let era = z.div_euclid(146097);
    let doe = z - era * 146097;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    yoe + era * 400 + i64::from(m <= 2)
}

/// The epoch day of a rule date in `year`.
fn day_of(year: i64, d: RuleDate) -> i64 {
    let jan1 = days_from_civil(year, 1, 1);
    match d {
        RuleDate::Julian(n) => {
            let n = n as i64;
            jan1 + n - 1 + i64::from(is_leap(year) && n >= 60)
        }
        RuleDate::Zero(n) => jan1 + n as i64,
        RuleDate::Month(m, w, wd) => {
            let first = days_from_civil(year, m as i64, 1);
            // 1970-01-01 was a Thursday (4).
            let first_wd = (first + 4).rem_euclid(7);
            let mut day = first + (wd as i64 - first_wd).rem_euclid(7) + (w as i64 - 1) * 7;
            let next_month = if m == 12 {
                days_from_civil(year + 1, 1, 1)
            } else {
                days_from_civil(year, m as i64 + 1, 1)
            };
            while day >= next_month {
                day -= 7;
            }
            day
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn at(y: i64, m: i64, d: i64, h: i64, mi: i64) -> i64 {
        days_from_civil(y, m, d) * 86400 + h * 3600 + mi * 60
    }

    #[test]
    fn offsets_and_transitions() {
        let ny = zone("America/New_York").expect("zone");
        assert_eq!(ny.offset_at(at(2024, 1, 15, 12, 0)), -5 * 3600);
        assert_eq!(ny.offset_at(at(2024, 7, 15, 12, 0)), -4 * 3600);
        // Rule years far beyond the table.
        assert_eq!(ny.offset_at(at(2200, 7, 15, 12, 0)), -4 * 3600);
        assert_eq!(ny.offset_at(at(2200, 12, 15, 12, 0)), -5 * 3600);
        // 2024-03-10 02:00 EST → 03:00 EDT (07:00 UT).
        assert_eq!(ny.next_transition(at(2024, 3, 1, 0, 0)), Some(at(2024, 3, 10, 7, 0)));
        assert_eq!(ny.previous_transition(at(2024, 3, 10, 7, 0)), Some(at(2023, 11, 5, 6, 0)));
        assert_eq!(ny.next_transition(at(2250, 3, 1, 0, 0)), Some(at(2250, 3, 10, 7, 0)));
        // The gap and the overlap.
        assert!(ny.possible(at(2024, 3, 10, 2, 30)).is_empty());
        assert_eq!(ny.possible(at(2024, 11, 3, 1, 30)).len(), 2);
        assert_eq!(ny.possible(at(2024, 6, 1, 12, 0)), vec![at(2024, 6, 1, 16, 0)]);
        // Southern hemisphere and negative DST.
        let syd = zone("Australia/Sydney").expect("zone");
        assert_eq!(syd.offset_at(at(2300, 1, 1, 0, 0)), 11 * 3600);
        assert_eq!(syd.offset_at(at(2300, 7, 1, 0, 0)), 10 * 3600);
        let dub = zone("europe/dublin").expect("zone");
        assert_eq!(dub.offset_at(at(2300, 7, 1, 0, 0)), 3600);
        assert_eq!(dub.offset_at(at(2300, 1, 1, 0, 0)), 0);
        assert_eq!(lookup("us/eastern"), Some(("US/Eastern", "America/New_York")));
        assert_eq!(lookup("etc/gmt"), Some(("Etc/GMT", "UTC")));
        assert_eq!(lookup("utc"), Some(("UTC", "UTC")));
        assert!(lookup("Mars/Olympus").is_none());
    }
}
